vector_store = {
    "customer_a_docs": [
        {"id": "a1", "text": "Refund policy for customer A."},
        {"id": "a2", "text": "Shipping details for customer A."},
    ],
    "customer_b_docs": [
        {"id": "b1", "text": "Refund policy for customer B."},
    ],
}

def search_collection(vector_store, collection_name, query_text):
    # a query searches one collection at a time
    collection = vector_store.get(collection_name, [])
    return [doc for doc in collection if "refund" in doc["text"].lower()]

results = search_collection(vector_store, "customer_a_docs", "refund policy")
print(f"Searching only customer_a_docs (multi tenant isolation):")
for r in results:
    print(f" {r}")

print(f"\nTotal collections in the database (the overhead of many collections): {len(vector_store)}")
print("customer_b_docs was never touched by this search,")
print("multi tenant isolation.")
